play.strudelCode:
// kajal's score — a tiny groove to remix ✦
// press play → then edit ANYTHING and hit update

setcps(0.5)

// drums — bd kick · sd snare · hh hats. try adding more!
$: s("bd ~ [~ bd] sd, [~ hh]*4").bank("RolandTR808").gain(.9)

// lazy keys — swap the notes, or .slow(4) it
$: note("<d3 f3 a3 c4>").s("gm_epiano1").room(.5).slow(2)

// melody — change the numbers, they're scale degrees
$: n("0 [2 4] 7 [4 2]").scale("D:minor:pentatonic").s("kalimba").room(.7).gain(.6)
